async function fulfill(request,result,headers=[],responseCode=200){if(result.videoBinary){assert(videoBytes.length);const header=Object.entries(request.request.headers).find(([key])=>key.toLowerCase()==='range');const match=header&&/^bytes=([0-9]+)-([0-9]*)$/.exec(header[1]);const start=match?Number(match[1]):0,end=match&&match[2]?Math.min(videoBytes.length-1,Number(match[2])):videoBytes.length-1;const selected=videoBytes.subarray(start,end+1);await cdp('Fetch.fulfillRequest',{requestId:request.requestId,responseCode:match?206:200,responseHeaders:[{name:'Content-Type',value:'video/mp4'},{name:'Accept-Ranges',value:'bytes'},{name:'Content-Length',value:String(selected.length)},...(match?[{name:'Content-Range',value:'bytes '+start+'-'+end+'/'+videoBytes.length}]:[])],body:selected.toString('base64')});return;}if(result.pdfBinary){await cdp('Fetch.fulfillRequest',{requestId:request.requestId,responseCode:200,responseHeaders:[{name:'Content-Type',value:'application/pdf'}],body:pdfBytes.toString('base64')});return;}const body=result&&result.status?result:{status:200,data:result};await cdp('Fetch.fulfillRequest',{requestId:request.requestId,responseCode:result.status===403?403:responseCode,responseHeaders:[{name:'Content-Type',value:'application/json'},...headers],body:Buffer.from(JSON.stringify(body)).toString('base64')});}
